fn run_with_timeout_and_stdin_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    stderr_mode: StderrMode,
    live_secrets: Vec<String>,
    stdin_payload: Option<Vec<u8>>,
) -> Result<CommandOutput, CommandError> {
    let mut child = std::process::Command::new(program)
        .args(args)
        .current_dir(cwd)
        .stdin(if stdin_payload.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| {
            if e.kind() == std::io::ErrorKind::NotFound {
                CommandError::NotFound {
                    program: program.to_string(),
                }
            } else {
                CommandError::Io {
                    program: program.to_string(),
                    message: e.to_string(),
                }
            }
        })?;

    if let Some(payload) = stdin_payload {
        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
        std::thread::spawn(move || {
            drop(stdin_pipe.write_all(&payload));
            drop(stdin_pipe.flush());
        });
    }

    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
    // when the child produces output while we wait for it to exit.
